    // Create an array of objects with book and original index
    const booksWithIndex = books.map((book, index) => ({ book, index }));

    // Comparator function
    const compare = (a, b) => {
        const aStr = a.book;
        const bStr = b.book;

        const aFirst = aStr[0] || '';
        const bFirst = bStr[0] || '';

        const aIsDigit = isDigit(aFirst);
        const bIsDigit = isDigit(bFirst);

        // Handle digit vs non-digit
        if (aIsDigit !== bIsDigit) {
            return aIsDigit ? -1 : 1;
        }

        // Compare first character ASCII codes
        const aCode = aFirst.charCodeAt(0);
        const bCode = bFirst.charCodeAt(0);
        if (aCode !== bCode) {
            return aCode - bCode;
