        // Compare lengths in descending order
        if (aStr.length !== bStr.length) {
            return bStr.length - aStr.length;
        }

        // Compare each character in reverse ASCII order
        for (let i = 0; i < aStr.length; i++) {
            const aCharCode = aStr.charCodeAt(i);
            const bCharCode = bStr.charCodeAt(i);
            if (aCharCode !== bCharCode) {
                return bCharCode - aCharCode;
            }
        }

        // All characters are same, retain original order
        return a.index - b.index;
    };

    // Sort the books with the comparator
    booksWithIndex.sort(compare);

    // Extract the sorted books
    return booksWithIndex.map(entry => entry.book);
